// Define the data types
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

// Define the operand structure
#[derive(Debug, Clone)]
pub struct NumpyOperand {
    pub dtype: NumpyDType,
}

// Define the rank of each data type
fn dtype_rank(dtype: NumpyDType) -> usize {
    match dtype {
        NumpyDType::Bool => 0,
        NumpyDType::Int8 => 1,
        NumpyDType::Int16 => 2,
        NumpyDType::Int32 => 3,
        NumpyDType::Int64 => 4,
        NumpyDType::Float32 => 5,
        NumpyDType::Float64 => 6,
        NumpyDType::Complex64 => 7,
        NumpyDType::Complex128 => 8,
    }
}

// Function to determine the resulting data type
#[verus::spec]
fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    // Precondition: the operands vector must not be empty
    assert!(!operands.is_empty());

    // Invariant: the result type must be one of the operand types
    let mut max_dtype = operands[0].dtype;
    let mut max_rank = dtype_rank(max_dtype);

    // Iterate through the operands to find the maximum data type
    for operand in &operands {
        let current_rank = dtype_rank(operand.dtype);
        if current_rank > max_rank {
            max_rank = current_rank;
            max_dtype = operand.dtype;
        }
    }

    // Ensure that the result type is at least as large as the rank of every operand's data type
    for operand in &operands {
        assert!(dtype_rank(operand.dtype) <= max_rank);
    }

    // Ensure that the result type is one of the maximum-ranked types present
    assert!(operands.iter().any(|op| op.dtype == max_dtype));

    // Return the determined maximum data type
    max_dtype
}

// Example usage
fn main() {
    let operands = vec![
        NumpyOperand { dtype: NumpyDType::Int8 },
        NumpyOperand { dtype: NumpyDType::Float32 },
        NumpyOperand { dtype: NumpyDType::Bool },
    ];

    let result = result_type(operands);
    println!("{:?}", result); // Should print Float32
}